/**
 * Element subset for the chemistry mini-lab.
 *
 * Same record shape as Chem Lab's src/data/elements.json (fields copied verbatim,
 * summaries trimmed to their first sentence), so the mini-lab can be lifted into
 * Chem Lab and pointed at the full 119-element dataset unchanged.
 * Generated by hand from chem-lab/src/data/elements.json — do not edit numbers.
 */
export interface ElementRecord {
  name: string;
  symbol: string;
  number: number;
  atomic_mass: number;
  category: string;
  period: number;
  group: number;
  phase: string;
  shells: number[];
  electron_configuration: string;
  summary: string;
  'cpk-hex': string | null;
}

/** Neutrons in the most common isotope ≈ mass number − protons. */
export const neutronsOf = (e: ElementRecord) => Math.round(e.atomic_mass) - e.number;

